import { after } from "next/server";

import { logPageView } from "../lib/analytics";

export default function Home() {
  after(() =>
    logPageView({
      path: "/",
      timestamp: new Date().toISOString(),
    })
  );

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Your page view is logged after the response.</p>
    </main>
  );
}
